proposal.source:
type enumeration = enum { daily, weekly }
type repository-name = repo-name
type view = choice(resource, market) {
 balances = ("balances", "portfolio")
 positions = ("positions", "usdm")
}
type symbol = text('[A-Z0-9]+', 2, 20)
type count = uint(0, 18446744073709551615)
rule previous-types(mode: enumeration, repo: repository-name, view: view, symbol: symbol, count: count) {
 require is-dir "~"
 run --sudo printf "%s:%s:%s:%s:%s:%s" "$mode" "$repo" "${view.resource}" "${view.market}" "$symbol" "$count"
}

